// Merged per-architecture CPU configuration for the vendored OpenCV build.
// Generated by CMake (see README.md for the exact commands), then combined:
//   - arm64:  CPU_BASELINE=NEON, CPU_DISPATCH= (build-arm64/cv_cpu_config.h)
//   - x86_64: CPU_BASELINE=SSE4_2 requested -> plain baseline, CPU_DISPATCH=
//             (build-x86_64/cv_cpu_config.h; SSE2 universal intrinsics are still
//              auto-enabled from __SSE2__ by cv_cpu_dispatch.h)
// CPU dispatch is OFF everywhere: no CV_CPU_DISPATCH per-ISA translation units.

#if defined(__aarch64__) || defined(__arm64__)

// OpenCV CPU baseline features

#define CV_CPU_COMPILE_NEON 1
#define CV_CPU_BASELINE_COMPILE_NEON 1

#define CV_CPU_BASELINE_FEATURES 0 \
    , CV_CPU_NEON \


// OpenCV supported CPU dispatched features



#define CV_CPU_DISPATCH_FEATURES 0 \

#else  // x86_64 and anything else: plain baseline

// OpenCV CPU baseline features

#define CV_CPU_BASELINE_FEATURES 0 \


// OpenCV supported CPU dispatched features



#define CV_CPU_DISPATCH_FEATURES 0 \

#endif
